-- Основание использования Oracle Recruiting Cloud (технический документ §5, §10; стенограмма §117): решение владельца
-- 2026-10-15 — как у Oracle Taleo (§60). Публичный поиск вакансий кадрового сайта работодателя на
-- <код>.fa.<зона>.oraclecloud.com (тот же REST-запрос, что делает его страница, без входа и без ключа) и текст вакансий;
-- robots.txt у сайтов нет (404); берутся только вакансии страны сбора; текст служит отбору и не переиздаётся.
INSERT INTO source_permission (scope, provider, decision, basis, checked_on) VALUES
('PROVIDER', 'oraclecloud', 'ALLOW', 'Решение владельца (стенограмма §117): публичный поиск и тексты вакансий кадрового сайта работодателя на Oracle Recruiting Cloud; без входа и ключа; только вакансии страны сбора; текст служит отбору и не переиздаётся', DATE '2026-10-15');
